class PredictionChain:

    def __init__(self, models: Optional[List[Any]]=None):
        self.models = models if models is not None else []

    def add_model(self, model: Any):
        self.models.append(model)

    def run(self, input_data: pd.DataFrame, *, forecast_period: int, freq: str) -> pd.DataFrame:
        if not self.models:
            print('[WARNING] PredictionChain: No models added. Returning input data as is.')
            if not isinstance(input_data.index, pd.DatetimeIndex):
                input_data_copy = input_data.copy()
                input_data_copy['timestamp_dummy'] = pd.date_range(start='2023-01-01', periods=len(input_data), freq='D')
                input_data_copy = input_data_copy.set_index('timestamp_dummy')
                return input_data_copy
            return input_data.copy()
        current_data = input_data.copy()
        predictions = []
        for (i, model) in enumerate(self.models):
            print(f'[INFO] PredictionChain: Running model {i + 1}/{len(self.models)} -- {type(model).__name__}')
            try:
                if 'value' in current_data.columns:
                    last_date = current_data.index[-1] if isinstance(current_data.index, pd.DatetimeIndex) else pd.to_datetime(current_data.index.max())
                    if not isinstance(last_date, pd.Timestamp):
                        last_date = pd.to_datetime(last_date)
                    prediction_index = pd.date_range(start=last_date + pd.Timedelta(days=1), periods=forecast_period, freq=freq)
                    model_prediction = model.process(current_data.copy(), forecast_period=forecast_period, freq=freq)
                    predictions.append(model_prediction)
                    print(f'[INFO] PredictionChain: Dummy predictions generated for {forecast_period} periods.')
                else:
                    print("[WARNING] PredictionChain: No 'value' column for dummy prediction. Skipping model.")
            except AttributeError:
                print(f"[ERROR] Model {i + 1} does not have a 'predict' method or it failed.")
                return pd.DataFrame()
            except Exception as e:
                print(f'[ERROR] PredictionChain: Error running model {i + 1}: {e}')
                return pd.DataFrame()
        final_prediction = predictions[0]
        for prediction in predictions[1:]:
            if 'quantum_flux' in prediction.columns:
                if 'quantum_flux' not in final_prediction.columns:
                    final_prediction['quantum_flux'] = 0
                final_prediction['quantum_flux'] += prediction['quantum_flux']
        if 'quantum_flux' in final_prediction.columns:
            final_prediction['yhat'] += final_prediction['quantum_flux']
        return final_prediction

