@dataclass(frozen=True, slots=True)
class OntologyReportAudit:
    """
    Immutable ontology audit artifact.

    Contains:

        - ontology mapping observations
        - evidence metadata
        - source contract identity

    Does not:

        - perform ontology mapping
        - resolve semantic conflicts
        - enforce domain interpretation
    """
    source_contract_version: str
    ontology_engine: str
    observations: Tuple[OntologyMappingObservation, ...]
    metadata: Mapping[str, Any] | None = None
    version: str = VERSION

    def __post_init__(self) -> None:
        _validate_string('source_contract_version', self.source_contract_version)
        _validate_string('ontology_engine', self.ontology_engine)
        if not isinstance(self.observations, tuple):
            raise OntologyAuditError('OBSERVATIONS_MUST_BE_TUPLE')
        for observation in self.observations:
            if not isinstance(observation, OntologyMappingObservation):
                raise OntologyAuditError('INVALID_ONTOLOGY_OBSERVATION')
        if self.metadata is not None:
            if not isinstance(self.metadata, Mapping):
                raise OntologyAuditError('METADATA_MUST_BE_MAPPING')
        _validate_string('version', self.version)

    @property
    def observation_count(self) -> int:
        """
        Deterministic ontology observation count.
        """
        return len(self.observations)

    @property
    def passed(self) -> bool:
        """
        Evidence completion state.

        Does not evaluate ontology correctness.
        """
        return all((item.status.upper() == 'OK' for item in self.observations))

    def mapped_fields(self) -> Tuple[str, ...]:
        """
        Deterministic mapped field identity list.
        """
        return tuple((item.field for item in self.observations))

    def ontology_ids(self) -> Tuple[str, ...]:
        """
        Deterministic ontology identifier list.
        """
        return tuple((item.ontology_id for item in self.observations))

