class ParsingState(DataProcessingState):
    """
    ParsingState HQ2 — Tryb C (auto-detect):

    - DataFrame → używamy bez parsowania
    - JSON / JSONL / NDJSON / XML → JsonXmlParserOrchestrator (HQ2)
    - CSV / TSV / Excel / Parquet → IntelligentParser (legacy)
    - Binary → BinaryFileParser (legacy)
    """

    def process(self) -> 'ProcessingContext':
        logger.info(f'[ParsingState] Start — źródło: {self.context.data_source}')
        if hasattr(self.agent, 'progress') and self.agent.progress:
            self.agent.progress.update_step('Wczytywanie i parsowanie danych', progress=10)
        if isinstance(self.context.data_source, pd.DataFrame):
            self.context.raw_df = self.context.data_source.copy()
            logger.info('[ParsingState] Źródło to DataFrame — pomijam parsowanie pliku.')
            return self._post_parse_pipeline()
        if isinstance(self.context.data_source, (str, Path)):
            file_path = Path(self.context.data_source)
            if not file_path.exists():
                logger.error(f'[ParsingState] Plik nie istnieje: {file_path}')
                return self.context
            try:
                self.context.file_fingerprint = self.agent.fingerprint_engine.generate_full_fingerprint(file_path)
            except Exception as e:
                logger.warning(f'[ParsingState] Fingerprint nieudany: {e}')
                self.context.file_fingerprint = None
            suffix = file_path.suffix.lower()
            if suffix in {'.json', '.jsonl', '.ndjson', '.xml'}:
                try:
                    orchestrator = self.agent.jsonxml_orchestrator
                    pre = orchestrator.run_pre_mapping(raw_input=str(file_path))
                    post = orchestrator.run_post_mapping(pre_result=pre, user_mapping={}, context={})
                    df = post.get('dataframe')
                    if not isinstance(df, pd.DataFrame):
                        logger.error('[ParsingState] HQ2 Orchestrator nie zwrócił DataFrame.')
                        return self.context
                    self.context.raw_df = df.copy()
                    self.context.parsing_variants_info = {'ontology_report': post.get('ontology_report', {}), 'schema_report': post.get('schema_report', {}), 'variant_report': post.get('variant_report', {})}
                    logger.info(f'[ParsingState] HQ2 JSON/XML parser OK — shape={df.shape}')
                    return self._post_parse_pipeline()
                except Exception as e:
                    logger.exception(f'[ParsingState] Błąd HQ2 Orchestrator: {e}')
                    return self.context
            try:
                parsing_result = self.agent.intelligent_parser.intelligent_parse(file_path=str(file_path), **self.context.initial_kwargs)
                if parsing_result and 'dataframe' in parsing_result:
                    self.context.raw_df = parsing_result['dataframe']
                    self.context.parsing_variants_info = parsing_result.get('variants_info', {})
                elif suffix == '.csv':
                    self.context.raw_df = pd.read_csv(file_path)
                    logger.info('[ParsingState] Fallback: pd.read_csv')
            except Exception as e:
                logger.exception(f'[ParsingState] IntelligentParser error: {e}')
                return self.context
        else:
            logger.error(f'[ParsingState] Nieobsługiwany typ źródła: {type(self.context.data_source)}')
            return self.context
        return self._post_parse_pipeline()

    def _post_parse_pipeline(self) -> 'ProcessingContext':
        df = self.context.raw_df
        if df is None or (isinstance(df, pd.DataFrame) and df.empty):
            logger.error('[ParsingState] Ramka danych pusta po parsowaniu.')
            return self.context
        numeric_cols = df.select_dtypes(include=np.number).columns
        self.context.coercion_nan_cols = [c for c in numeric_cols if df[c].isnull().any()]
        unify_result = self.agent.target_unifier.unify_target_column(df, self.context.target_column_name)
        if isinstance(unify_result, dict) and unify_result.get('status') == 'AMBIGUOUS':
            self.context.requires_user_input = 'target_selection'
            self.context.user_input_data = {'suggested_targets': unify_result.get('candidates', []), 'dataframe': df}
            self.context.processed_df = df
            return self.context
        if isinstance(unify_result, tuple):
            (df, target) = unify_result
            self.context.raw_df = df
            self.context.target_column_name = target
        else:
            logger.error('[ParsingState] unify_target_column zwrócił nieoczekiwany typ.')
        try:
            (parsed_df, has_time, date_col) = self.agent.date_parser.parse_and_prepare(df, index_col=self.context.initial_kwargs.get('date_column'))
            self.context.date_column_name = date_col
            self.context.raw_df = parsed_df.copy()
            self.context.processed_df = parsed_df.copy()
        except Exception as e:
            logger.error(f'[ParsingState] DateParser error: {e}')
            self.context.processed_df = df.copy()
        return self.context

