class ReportProcessor(Agent[ReportContext, ReportArtifacts]):
    """
    Agent odpowiedzialny za pobranie surowego raportu, jego parsowanie 
    zgodnie z regułami i zapisanie przetworzonych danych.
    """

    def __init__(self, *args, **kwargs):
        """
        Inicjalizuje agenta i konwertuje wejściowy słownik kontekstu (Dict) 
        na bezpieczny model Pydantic (ReportContext).
        """
        super().__init__(*args, **kwargs)
        if not isinstance(self.context, ReportContext):
            try:
                self.context = ReportContext.model_validate(self.context)
                self._log_debug('Context successfully validated and cast to ReportContext.')
            except ValidationError as e:
                self._log_error('Initial context validation failed for ReportContext.', exc_info=True)
                raise ValueError(f'Invalid context for ReportProcessor: {e}') from e

    def process(self, data: Any=None, context: Optional[ReportContext]=None, **kwargs) -> AgentOperationResult[ReportContext, ReportArtifacts]:
        """
        Główna logika przetwarzania: pobieranie, parsowanie i walidacja.

        :param data: Ignorowany w tym agencie; dane pobierane są z context.report_source_url.
        :param context: Kopia bieżącego ReportContext (zabezpieczona kopia dla process).
        :param kwargs: Dodatkowe argumenty (np. timeout).
        :returns: AgentOperationResult zawierający ReportArtifacts lub błąd.
        """
        self._log_info(f'Processing report from URL: {context.report_source_url}')
        raw_data = self._simulate_fetch(context.report_source_url, kwargs.get('timeout', 30))
        if not raw_data:
            return AgentOperationResult(error=RuntimeError(f'Failed to fetch data from {context.report_source_url}'))
        self.update_context(raw_report_content=raw_data)
        self._log_debug(f'Raw content size updated: {len(raw_data)} bytes.')
        (processed_data, errors, num_records) = self._simulate_parse(raw_data, context.parse_rules)
        try:
            artifacts = ReportArtifacts(status_code=200 if not errors else 207, num_records=num_records, processed_file_path=f'artifacts/{context.request_id}_processed.json', errors=errors)
            self._log_info(f'Successfully processed {num_records} records with {len(errors)} errors.')
            return AgentOperationResult(artifacts=artifacts)
        except ValidationError as e:
            self._log_error('Artifacts validation failed.', exc_info=True)
            return AgentOperationResult(error=e)
        except Exception as e:
            self._log_error('Unexpected error during processing.', exc_info=True)
            return AgentOperationResult(error=e)

    def _simulate_fetch(self, url: str, timeout: int) -> Optional[str]:
        """ Symuluje pobieranie danych. """
        self._log_debug(f'Simulating fetch with timeout={timeout}s...')
        if 'fail' in url:
            return None
        return f'Raw Report Content: {url} - Generated at {self.request_id}'

    def _simulate_parse(self, content: str, rules: Dict[str, str]) -> tuple[Any, List[str], int]:
        """ Symuluje parsowanie raportu. """
        errors: List[str] = []
        if not rules:
            errors.append('No parsing rules provided; using default logic.')
        lines = content.split('\n')
        num_records = len(lines)
        if num_records > 1:
            errors.append(f'Sample parsing error on record {num_records // 2}.')
        processed_data = {'summary': f'Parsed {num_records} records.'}
        return (processed_data, errors, num_records)

