def validate_registry_entry(entry: RegistryEntry) -> None:
    """
    Validate registry entry invariants.

    Validation is structural only.
    """
    if not isinstance(entry, RegistryEntry):
        raise RegistryEntryError('INVALID_REGISTRY_ENTRY')
    fields = (('name', entry.name), ('kind', entry.kind), ('version', entry.version), ('owner', entry.owner))
    for (field_name, value) in fields:
        if not isinstance(value, str):
            raise RegistryEntryError(f'{field_name.upper()}_MUST_BE_STRING')
        if not value.strip():
            raise RegistryEntryError(f'{field_name.upper()}_EMPTY')
    if not isinstance(entry.metadata, tuple):
        raise RegistryEntryError('METADATA_MUST_BE_TUPLE')
    for item in entry.metadata:
        if not isinstance(item, tuple) or len(item) != 2:
            raise RegistryEntryError('INVALID_METADATA_ENTRY')

