@dataclass(frozen=True, slots=True)
class ValidationClosure:
    """
    Immutable validation lifecycle closure artifact.

    Contains:

        - validation events
        - validator identity
        - pipeline identity
        - closure state

    Does not:

        - execute validation
        - evaluate remediation
        - modify runtime state
    """
    pipeline: str
    validator: str
    events: Tuple[ValidationEvent, ...]
    closed: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        for (name, value) in (('pipeline', self.pipeline), ('validator', self.validator)):
            if not isinstance(value, str):
                raise ValidationClosureError(f'{name.upper()}_MUST_BE_STRING')
            if not value.strip():
                raise ValidationClosureError(f'{name.upper()}_EMPTY')
        if not isinstance(self.events, tuple):
            raise ValidationClosureError('EVENTS_MUST_BE_TUPLE')
        for event in self.events:
            if not isinstance(event, ValidationEvent):
                raise ValidationClosureError('INVALID_VALIDATION_EVENT')
        if not isinstance(self.closed, bool):
            raise ValidationClosureError('CLOSED_MUST_BE_BOOL')

    @property
    def event_count(self) -> int:
        """
        Deterministic validation event count.
        """
        return len(self.events)

    @property
    def passed(self) -> bool:
        """
        Evidence-level closure state.

        Does not execute validation.
        """
        return self.closed and all((event.status.upper() == 'OK' for event in self.events))

