def audit_ingestion_structure(report: IngestionStructureReport) -> IngestionStructureAuditReport:
    """
    Deterministic structure governance evaluation.

    Input:
        immutable CORE structure facts

    Output:
        immutable AUDIT evidence artifact

    Guarantees:
        - no mutation
        - no repair
        - no inference
    """
    if not isinstance(report, IngestionStructureReport):
        raise StructureAuditError('INVALID_STRUCTURE_REPORT_SOURCE')
    issues: list[StructureAuditIssue] = []
    if report.total_nodes < 0:
        issues.append(StructureAuditIssue(rule_id='STRUCTURE.REPORT.TOTAL_NODES.NON_NEGATIVE', severity='ERROR', message='total_nodes cannot be negative'))
    if report.max_depth < 0:
        issues.append(StructureAuditIssue(rule_id='STRUCTURE.REPORT.MAX_DEPTH.NON_NEGATIVE', severity='ERROR', message='max_depth cannot be negative'))
    for node in report.nodes:
        if node.depth < 0:
            issues.append(StructureAuditIssue(rule_id='STRUCTURE.NODE.DEPTH.NON_NEGATIVE', severity='ERROR', message='node depth cannot be negative', path=node.path))
        if node.children_count < 0:
            issues.append(StructureAuditIssue(rule_id='STRUCTURE.NODE.CHILDREN.NON_NEGATIVE', severity='ERROR', message='children_count cannot be negative', path=node.path))
        if not node.path:
            issues.append(StructureAuditIssue(rule_id='STRUCTURE.NODE.PATH.REQUIRED', severity='ERROR', message='node path cannot be empty'))
    return IngestionStructureAuditReport(audit_version=VERSION, source_contract_version=report.version, valid=len(issues) == 0, issues=tuple(issues))

