class SerializationState(DataProcessingState):
    """
    Piąty etap: finalizacja, zapis i budowa artefaktów.
    """

    def process(self) -> 'ProcessingContext':
        df = self.context.processed_df
        if df is None or (isinstance(df, pd.DataFrame) and df.empty):
            logger.error('[SerializationState] Brak danych do finalizacji.')
            return self.context
        if hasattr(self.agent, 'progress') and self.agent.progress:
            self.agent.progress.update_step('Zapisywanie wyników', progress=100)
        logger.info('[SerializationState] Finalizacja artefaktów.')
        final_df = df.copy()
        date_strings = final_df.index.strftime('%Y-%m-%d').tolist() if hasattr(final_df.index, 'strftime') else []
        if DATE_STR_COL in final_df.columns:
            final_df = final_df.drop(columns=[DATE_STR_COL])
        output_path = None
        try:
            output_path = self.agent.serializer.save_data(data=final_df, file_prefix='processed_data')
        except Exception as e:
            logger.error(f'[SerializationState] Błąd zapisu: {e}')
        target = self.context.target_column_name
        artifacts: Dict[str, Any] = {'filepath': output_path, 'dataframe': final_df, 'date_strings': date_strings, 'target_name': target, 'file_fingerprint': getattr(self.context, 'file_fingerprint', None), 'parsing_summary': getattr(self.context, 'parsing_variants_info', {}), 'timestamp': pd.Timestamp.now().isoformat()}
        if target:
            for comp in ['trend', 'seasonal', 'resid', 'residual']:
                col = f'{target}_{comp}'
                if col in final_df.columns:
                    artifacts[comp] = final_df[col]
        self.context.final_artifacts = artifacts
        self.context.processed_df = final_df
        logger.info('[SerializationState] Zakończono proces HQ2.')
        return self.context

