class SynchronizationController:

    def __init__(self, config=None):
        self.config = config if config else {}
        self.use_golden_spiral = self.config.get('use_golden_spiral', False)

    def compute_sync_index(self, df):
        """
        Computes a synchronization index based on optional golden spiral geometry.
        Parameters:
            df (pd.DataFrame): Dataframe containing at least 'ds' and optionally spiral features
        Returns:
            pd.Series: synchronization index
        """
        sync_index = np.zeros(len(df))
        if self.use_golden_spiral and 'spiral_x' in df and ('spiral_y' in df):
            angle = np.arctan2(df['spiral_y'], df['spiral_x'])
            sync_index = np.sin(angle) * np.cos(angle * 3)
        else:
            sync_index = np.sin(np.linspace(0, 2 * np.pi, len(df)))
        return pd.Series(sync_index, name='sync_index')

