    Stateless deterministic projection operator.

    Input:
        immutable EventContract stream

    Output:
        immutable AuditFactSet artifact

    No:
        - mutation
        - interpretation
        - decisions
    """
    __slots__ = ()

    def project(self, events: Tuple[EventContract, ...]) -> AuditFactSet:
        """
