@dataclass(frozen=True, slots=True)
class DetectionSparsityContract:
    total_records: int
    null_count: int
    empty_string_count: int
    sparsity_ratio: float
    version: str = VERSION

    def __post_init__(self) -> None:
        for (field_name, value) in (('total_records', self.total_records), ('null_count', self.null_count), ('empty_string_count', self.empty_string_count)):
            if not isinstance(value, int):
                raise DetectionSparsityContractError(f'{field_name.upper()}_MUST_BE_INT')
            if value < 0:
                raise DetectionSparsityContractError(f'{field_name.upper()}_MUST_BE_NON_NEGATIVE')
        if not isinstance(self.sparsity_ratio, float):
            raise DetectionSparsityContractError('SPARSITY_RATIO_MUST_BE_FLOAT')
        if not 0.0 <= self.sparsity_ratio <= 1.0:
            raise DetectionSparsityContractError('SPARSITY_RATIO_MUST_BE_BETWEEN_0_AND_1')
        if self.null_count + self.empty_string_count > self.total_records:
            raise DetectionSparsityContractError('MISSING_RECORDS_EXCEED_TOTAL_RECORDS')
        if not isinstance(self.version, str):
            raise DetectionSparsityContractError('VERSION_MUST_BE_STRING')
        if not self.version.strip():
            raise DetectionSparsityContractError('VERSION_EMPTY')

