@dataclass(frozen=True, slots=True)
class QualityResultContract:
    run_id: str
    context: QualityContextContract
    scorecard: QualityOverallScorecardContract
    evaluations: Sequence[QualityRuleEvaluationContract]
    circuit_breaker: QualityRemediationHaltContract | None
    telemetry: QualityTelemetryContract
    diagnostics: Sequence[QualityDiagnosticContract]
    is_success: bool
    version: str = VERSION

    def __post_init__(self) -> None:
        if not isinstance(self.run_id, str):
            raise QualityResultContractError('RUN_ID_MUST_BE_STRING')
        if not self.run_id.strip():
            raise QualityResultContractError('RUN_ID_EMPTY')
        if not isinstance(self.context, QualityContextContract):
            raise QualityResultContractError('CONTEXT_MUST_BE_CONTRACT')
        if not isinstance(self.scorecard, QualityOverallScorecardContract):
            raise QualityResultContractError('SCORECARD_MUST_BE_CONTRACT')
        if not isinstance(self.evaluations, Sequence):
            raise QualityResultContractError('EVALUATIONS_MUST_BE_SEQUENCE')
        for eval_record in self.evaluations:
            if not isinstance(eval_record, QualityRuleEvaluationContract):
                raise QualityResultContractError('EVALUATIONS_MUST_CONTAIN_CONTRACTS')
        if self.circuit_breaker is not None:
            if not isinstance(self.circuit_breaker, QualityRemediationHaltContract):
                raise QualityResultContractError('CIRCUIT_BREAKER_MUST_BE_CONTRACT_OR_NONE')
        if not isinstance(self.telemetry, QualityTelemetryContract):
            raise QualityResultContractError('TELEMETRY_MUST_BE_CONTRACT')
        if not isinstance(self.diagnostics, Sequence):
            raise QualityResultContractError('DIAGNOSTICS_MUST_BE_SEQUENCE')
        for diag in self.diagnostics:
            if not isinstance(diag, QualityDiagnosticContract):
                raise QualityResultContractError('DIAGNOSTICS_MUST_CONTAIN_CONTRACTS')
        if not isinstance(self.is_success, bool):
            raise QualityResultContractError('IS_SUCCESS_MUST_BE_BOOL')
        if not isinstance(self.version, str):
            raise QualityResultContractError('VERSION_MUST_BE_STRING')
        if not self.version.strip():
            raise QualityResultContractError('VERSION_EMPTY')

